contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 amount) public {
        require(to != address(0), "to");
        require(amount > 0, "amount");

        ISize.DepositParams memory p = ISize.DepositParams({
            token: address(c.data().underlyingBorrowToken),
            amount: amount,
            to: to
        });

        IERC20Metadata t = c.data().underlyingBorrowToken;

        require(t.balanceOf(address(this)) >= amount, "balance");
        t.approve(address(c), amount);

        uint256 supplyBefore = c.data().borrowAToken.totalSupply();
        uint256 toBalBefore = c.data().borrowAToken.balanceOf(to);

        c.deposit(p);

        uint256 supplyAfter = c.data().borrowAToken.totalSupply();
        uint256 toBalAfter = c.data().borrowAToken.balanceOf(to);

        assert(toBalAfter - toBalBefore == amount && supplyAfter - supplyBefore == amount);
    }
}

