contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 seed, address to, uint256 amount, bytes32 roleKey) public payable {
        require(address(c) != address(0));

        // Read the risk config before any mutation.
        InitializeRiskConfigParams memory before = c.riskConfig();

        // The core general rule: the protocol's initialization invariant must hold at all times.
        // These are the exact conditions enforced by validateInitializeRiskConfigParams.
        assert(
            before.crOpening >= PERCENT
                && before.crLiquidation >= PERCENT
                && before.crOpening > before.crLiquidation
                && before.minimumCreditBorrowAToken > 0
                && before.minTenor > 0
                && before.maxTenor > before.minTenor
        );

        // Perform a state-mutating call that does not require any role/authorization for the caller
        // beyond being a user: setting a user configuration for the test contract itself.
        uint256[] memory noIds = new uint256[](0);
        c.setUserConfiguration(SetUserConfigurationParams({
            openingLimitBorrowCR: 0,
            allCreditPositionsForSaleDisabled: false,
            creditPositionIdsForSale: false,
            creditPositionIds: noIds
        }));

        // The risk configuration must be unchanged by an unrelated user operation.
        InitializeRiskConfigParams memory afterCfg = c.riskConfig();
        assert(
            afterCfg.crOpening == before.crOpening
                && afterCfg.crLiquidation == before.crLiquidation
                && afterCfg.minimumCreditBorrowAToken == before.minimumCreditBorrowAToken
                && afterCfg.borrowATokenCap == before.borrowATokenCap
                && afterCfg.minTenor == before.minTenor
                && afterCfg.maxTenor == before.maxTenor
        );
    }

    receive() external payable {}
}

