contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 creditPositionId, bool forSale) public payable {
        address me = address(this);

        // Encode the parameters into a "transfer" from the test contract to itself to prove a credit position
        // is only created when the contract is set up in advance. The SizeView layer needs a valid
        // credit position ID, which requires the protocol to be initialized and a debt/credit pair created.
        // Since we only have one public entry point, we use the exposed public setters on ISize that work
        // on already-created positions, and we drive the sale flag for one existing credit position.

        // Read the current credit position state before the call.
        CreditPosition memory before = c.getCreditPosition(creditPositionId);
        uint256 debtPositionId = before.debtPositionId;

        uint256[] memory ids = new uint256[](1);
        ids[0] = creditPositionId;

        // Top-level state-changing call on c.
        c.setUserConfiguration(
            SetUserConfigurationParams({
                openingLimitBorrowCR: 0,
                allCreditPositionsForSaleDisabled: false,
                creditPositionIdsForSale: forSale,
                creditPositionIds: ids
            })
        );

        CreditPosition memory afterPos = c.getCreditPosition(creditPositionId);

        assert(afterPos.forSale == forSale);
    }

    receive() external payable {}
}

