contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 creditPositionId) public payable {
        require(creditPositionId != 0, "invalid credit position id");

        // make sure the credit position exists and has nonzero credit
        uint256 creditBefore = c.getCreditPosition(creditPositionId).credit;
        require(creditBefore > 0, "position has no credit");

        // only continue if the borrower's CR is at least 1e18, otherwise self-liquidate would fail for other reasons
        uint256 cr = c.collateralRatio(creditBefore == 0 ? address(0) : address(0));
        require(cr >= 1e18, "borrower is at a loss, test does not apply");

        bool reverted;
        try c.selfLiquidate(SelfLiquidateParams({creditPositionId: creditPositionId})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 creditPositionId) public payable {
        require(creditPositionId != 0, "invalid credit position id");

        // ensure the position exists and has nonzero credit
        uint256 creditBefore = c.getCreditPosition(creditPositionId).credit;
        require(creditBefore > 0, "position has no credit");

        // only apply the rule when the borrower's CR is at least 1e18
        address borrower = c.getLoanStatus(creditPositionId) == LoanStatus.ACTIVE
            ? c.getCreditPosition(creditPositionId).lender
            : address(0);
        require(c.collateralRatio(borrower) >= 1e18, "borrower is at a loss, test does not apply");

        bool reverted;
        try c.selfLiquidate(SelfLiquidateParams({creditPositionId: creditPositionId})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && c.getCreditPosition(creditPositionId).credit == creditBefore);
    }

    receive() external payable {}
}

